package com.alsafa.native4.core;import android.database.Cursor;/** Read-only local inventory summary for home UI. */public final class InventorySummaryStore{private final CoreStore.DbProvider p;public InventorySummaryStore(CoreStore.DbProvider p){this.p=p;}public Summary read(){try(Cursor c=p.db().rawQuery("SELECT COUNT(*),COALESCE(SUM(CASE WHEN quantity<=1 THEN 1 ELSE 0 END),0),COALESCE(SUM(quantity),0) FROM products WHERE deleted_at IS NULL",null)){if(c.moveToFirst())return new Summary(c.getInt(0),c.getInt(1),c.getInt(2));return new Summary(0,0,0);}}public static final class Summary{public final int products,lowStock,units;Summary(int p,int l,int u){products=p;lowStock=l;units=u;}}}